orders = [12, 50, 80, 3]

def buggy_total(quantity):
    cost = quantity * 0.20
    if quantity > 50:
        cost = cost * 0.90
    cost = cost + 1.00
    return round(cost, 2)

def correct_total(quantity):
    cost = quantity * 0.20
    if quantity >= 50:
        cost = cost * 0.90
    cost = cost + 1.00
    return round(cost, 2)

mismatch = any(buggy_total(q) != correct_total(q) for q in orders)
print(2 if mismatch else 0)

def step_total(days):
    total = 0
    for d in days:
        if d >= 0:
            total += d
    return total

def atm_withdrawal(balance, amount, daily_limit):
    if amount <= 0:
        return "invalid amount"
    if amount > daily_limit:
        return "exceeds daily limit"
    if amount > balance:
        return "insufficient funds"
    return "approved"

def parcel_fee(weight_kg, express):
    total = 5.0
    extra = max(0, weight_kg - 1)
    total += extra * 2.0
    if express:
        total *= 1.5
    if total > 50:
        total = 50.0
    return round(total, 2)

def check_baggage(weight_kg, bag_count):
    if bag_count < 1 or bag_count > 3:
        return "invalid bag count"
    if weight_kg <= 0:
        return "invalid weight"
    if weight_kg > 23:
        return "overweight"
    return "accepted"

def total_ascent(elevations):
    total = 0
    for i in range(1, len(elevations)):
        diff = elevations[i] - elevations[i - 1]
        if diff > 0:
            total += diff
    return total

def select_finalists(entries, min_score):
    result = []
    for name, score, checked_in in entries:
        if checked_in and score >= min_score:
            result.append(name)
    return result

def count_dry_cells(moisture, threshold):
    count = 0
    for row in moisture:
        for value in row:
            if value < threshold:
                count += 1
    return count

def first_out_of_range(readings, low, high):
    for value in readings:
        if value < low or value > high:
            return value
    return None

def nth_from_last(names, n):
    if n < 0 or n >= len(names):
        return None
    return names[len(names) - 1 - n]

def final_state(commands):
    state = "stopped"
    for cmd in commands:
        if state == "stopped":
            if cmd == "play":
                state = "playing"
        elif state == "playing":
            if cmd == "pause":
                state = "paused"
            elif cmd == "stop":
                state = "stopped"
        elif state == "paused":
            if cmd == "play":
                state = "playing"
            elif cmd == "stop":
                state = "stopped"
    return state

def first_index(times, target):
    lo, hi = 0, len(times) - 1
    result = -1
    while lo <= hi:
        mid = (lo + hi) // 2
        if times[mid] == target:
            result = mid
            hi = mid - 1
        elif times[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return result

